const { withProjectBuildGradle } = require("expo/config-plugins");

const repositoryBlock = `
    // @generated by with-scoped-android-maven-repositories
    exclusiveContent {
      forRepository {
        maven { url = uri("https://repository.map.naver.com/archive/maven") }
      }
      filter { includeGroup("com.naver.maps") }
    }
    exclusiveContent {
      forRepository {
        maven { url = uri("https://devrepo.kakao.com/nexus/content/groups/public/") }
      }
      filter { includeGroup("com.kakao.sdk") }
    }`;

function withScopedAndroidMavenRepositories(config) {
  return withProjectBuildGradle(config, (gradleConfig) => {
    if (gradleConfig.modResults.language !== "groovy") {
      throw new Error("Scoped Android repositories require Groovy build.gradle.");
    }
    if (gradleConfig.modResults.contents.includes("with-scoped-android-maven-repositories")) {
      return gradleConfig;
    }
    const repositories = /allprojects\s*\{\s*repositories\s*\{/u;
    if (!repositories.test(gradleConfig.modResults.contents)) {
      throw new Error("Android allprojects repositories block was not found.");
    }
    gradleConfig.modResults.contents = gradleConfig.modResults.contents.replace(
      repositories,
      (match) => `${match}${repositoryBlock}`,
    );
    return gradleConfig;
  });
}

module.exports = withScopedAndroidMavenRepositories;
